Here is the root cause:
The bug arises from the inability of the kernel to handle hardware breakpoint exceptions correctly on ARM and AArch64 architectures, leading to an infinite loop during the Sigtrap test. This occurs because the kernel does not step over the faulting instruction as expected, causing the test to hang indefinitely.

Here is the patch:
 #include "../perf-sys.h"

-/*
- * PowerPC and S390 do not support creation of instruction breakpoints using the
- * perf_event interface.
- *
- * Just disable the test for these architectures until these issues are
- * resolved.
- */
-#if defined(__powerpc__) || defined(__s390x__)
-#define BP_ACCOUNT_IS_SUPPORTED 0
-#else
-#define BP_ACCOUNT_IS_SUPPORTED 1
-#endif
-
 #define NUM_THREADS 5


 static int test__sigtrap(struct test_suite *test __maybe_unused, int subtest __maybe_unused)
 {
 	struct perf_event_attr attr = make_event_attr();
 	struct sigaction action = {};
 	struct sigaction oldact;
 	pthread_t threads[NUM_THREADS];
 	pthread_barrier_t barrier;
 	char sbuf[STRERR_BUFSIZE];
 	int i, fd, ret = TEST_FAIL;

-	if (!BP_ACCOUNT_IS_SUPPORTED) {
+	if (!BP_SIGNAL_IS_SUPPORTED) {
 		pr_debug("Test not supported on this architecture");
 		return TEST_SKIP;
 	}

 	pthread_barrier_init(&barrier, NULL, NUM_THREADS + 1);

 	action.sa_flags = SA_SIGINFO | SA_NODEFER;
 	action.sa_sigaction = sigtrap_handler;
 	sigemptyset(&action.sa_mask);
 	if (sigaction(SIGTRAP, &action, &oldact)) {
 		pr_debug("FAILED sigaction(): %s\n", str_error_r(errno, sbuf, sizeof(sbuf)));
 		goto out;
 	}

 	fd = sys_perf_event_open(&attr, 0, -1, -1, perf_event_open_cloexec_flag());
 	if (fd < 0) {
 		pr_debug("FAILED sys_perf_event_open(): %s\n", str_error_r(errno, sbuf, sizeof(sbuf)));
 		goto out_restore_sigaction;
 	}

 	for (i = 0; i < NUM_THREADS; i++) {
 		if (pthread_create(&threads[i], NULL, test_thread, &barrier)) {
 			pr_debug("FAILED pthread_create(): %s\n", str_error_r(errno, sbuf, sizeof(sbuf)));
 			goto out_close_perf_event;
 		}
 	}

 	ret = run_stress_test(fd, threads, &barrier);

 out_close_perf_event:
 	close(fd);
 out_restore_sigaction:
 	sigaction(SIGTRAP, &oldact, NULL);
 out:
 	pthread_barrier_destroy(&barrier);
 	return ret;
 }



